#include <string>

class Solution {
public:
    int findKthDigit(int k) {
        long long digitLen = 1;
        long long count = 9;
        long long start = 1;
        while (k > digitLen * count) {
            k -= digitLen * count;
            digitLen++;
            count *= 10;
            start *= 10;
        }
        long long num = start + (k - 1) / digitLen;
        int idx = (k - 1) % digitLen;
        return std::to_string(num)[idx] - '0';
    }
};

